window.EL_CAPSULES = window.EL_CAPSULES || {};
Object.assign(window.EL_CAPSULES, {
  "p2:Oct:1": {"title": "Cuándo Nació Mi Ciudad", "steps": [{"type": "hook", "kicker": "Un viaje al pasado", "h": "¿Cuándo nació tu ciudad?", "scenario": "Marta pregunta a su abuelo: '¿Desde cuándo existe nuestro pueblo?' Su abuelo sonríe y saca un libro muy antiguo.", "body": "Cada ciudad y cada pueblo tiene una fecha de nacimiento. ¡Como tú, que naciste un día especial!"}, {"type": "theory", "kicker": "Historia de mi municipio", "h": "¿Cómo nace un municipio?", "body": "Hace muchos años, algunas personas eligieron un lugar para vivir juntas. Así empezó tu ciudad o pueblo. Ese momento se llama <b>fundación</b>.", "diagram": "<b>Datos de la fundación</b><br>- El año o siglo en que empezó<br>- Quién la fundó o por qué<br>- Cómo era al principio"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Un pequeño reto", "q": "¿Qué significa la 'fundación' de un municipio?", "opts": [{"t": "El momento en que empezó a existir", "ok": true}, {"t": "El nombre del alcalde actual", "ok": false}, {"t": "El color de la bandera", "ok": false}], "okMsg": "¡Genial! La fundación es el inicio de la historia de tu ciudad.", "noMsg": "Casi. La fundación es el momento en que la ciudad empezó a existir."}, {"type": "reflect", "kicker": "Mi ciudad, mi historia", "h": "Investiga en casa", "body": "Con ayuda de un adulto, busca información sobre el origen de tu municipio.", "prompt": "Escribe 3 datos clave: el año de fundación, quién la fundó y un dato curioso."}]},
  "p2:Oct:2": {"title": "Un Héroe de Mi Tierra", "steps": [{"type": "hook", "kicker": "Personas que dejaron huella", "h": "¿Quién hizo grande a tu ciudad?", "scenario": "En la plaza mayor hay una estatua. Pablo se pregunta: '¿Quién es esta persona tan importante?'", "body": "En cada ciudad vivieron personas especiales. Hicieron cosas que todavía recordamos hoy."}, {"type": "theory", "kicker": "Personajes históricos", "h": "¿Por qué recordamos a alguien?", "body": "Un personaje histórico es alguien que vivió hace tiempo y ayudó a su ciudad. Puede ser un rey, una escritora, un científico o un héroe local.", "diagram": "<b>Para conocer a un personaje</b><br>- Su nombre<br>- La época en que vivió<br>- Por qué es famoso"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Piensa un momento", "q": "¿Qué necesitamos saber sobre un personaje histórico?", "opts": [{"t": "Su nombre, su época y por qué es famoso", "ok": true}, {"t": "Solo su comida favorita", "ok": false}, {"t": "Solo el color de su ropa", "ok": false}], "okMsg": "¡Correcto! Esos datos nos ayudan a entender su importancia.", "noMsg": "Piensa de nuevo: necesitamos su nombre, su época y por qué es famoso."}, {"type": "reflect", "kicker": "Mi ciudad, mi historia", "h": "Investiga en casa", "body": "Busca con un adulto un personaje histórico de tu municipio.", "prompt": "Escribe su nombre, la época en que vivió y por qué es famoso."}]},
  "p2:Oct:3": {"title": "El Escudo de Mi Ciudad", "steps": [{"type": "hook", "kicker": "Símbolos con significado", "h": "¿Qué dibujo representa a tu ciudad?", "scenario": "Lucía ve un escudo en la puerta del ayuntamiento. Tiene un castillo, un árbol y unas estrellas.", "body": "Los escudos guardan mensajes escondidos. Cada dibujo cuenta algo importante de la historia del lugar."}, {"type": "theory", "kicker": "El escudo municipal", "h": "¿Qué es un escudo municipal?", "body": "Un escudo municipal es un dibujo que representa a tu ciudad. Cada símbolo dentro tiene un significado especial.", "diagram": "<b>Símbolos comunes en un escudo</b><br>- Castillos: fortalezas o historia<br>- Animales: fuerza o naturaleza<br>- Coronas: importancia real<br>- Colores: valores del lugar"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Un pequeño reto", "q": "¿Qué es el escudo municipal?", "opts": [{"t": "Un dibujo con símbolos que representa a la ciudad", "ok": true}, {"t": "Un tipo de comida típica", "ok": false}, {"t": "El nombre del río más cercano", "ok": false}], "okMsg": "¡Exacto! El escudo cuenta la historia de tu ciudad con símbolos.", "noMsg": "No exactamente. El escudo es un dibujo con símbolos que representa a la ciudad."}, {"type": "reflect", "kicker": "Mi ciudad, mi historia", "h": "Dibuja y explica", "body": "Copia y colorea el escudo de tu municipio.", "prompt": "Explica con 2-3 frases qué significan 2 de sus símbolos."}]},
  "p2:Oct:4": {"title": "Cuido la Ciudad Donde Vivo", "steps": [{"type": "hook", "kicker": "Un mensaje muy antiguo", "h": "¿Puedo cuidar mi ciudad?", "scenario": "Daniel recoge un papel del suelo en el parque y lo tira a la papelera. Su hermana sonríe: 'Así cuidas nuestra ciudad'.", "body": "Hace muchos años, Dios pidió a su pueblo que cuidara la ciudad donde vivían, aunque no fuera su hogar de siempre."}, {"type": "theory", "kicker": "La Biblia y mi ciudad", "h": "Buscad la paz de la ciudad", "body": "En la Biblia, Dios dijo a su pueblo que buscara el bien de su ciudad. Cuidar el lugar donde vivimos también es cuidar a las personas.", "diagram": "<b>Jeremías 29:7</b><br>'Buscad la paz de la ciudad a la cual os hice transportar.'<br>- Cuidar significa ayudar<br>- Cuidar significa respetar"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Piensa un momento", "q": "Según el versículo, ¿qué nos pide Dios sobre nuestra ciudad?", "opts": [{"t": "Buscar su paz y su bien", "ok": true}, {"t": "Mudarnos a otra ciudad", "ok": false}, {"t": "No hablar con nadie", "ok": false}], "okMsg": "¡Muy bien! Dios quiere que cuidemos y busquemos el bien de nuestra ciudad.", "noMsg": "Recuerda: el versículo pide buscar la paz y el bien de la ciudad."}, {"type": "reflect", "kicker": "Mi ciudad, mi historia", "h": "Mi ficha de la ciudad", "body": "Ya conoces la historia, un personaje y el escudo de tu municipio.", "prompt": "Escribe 2-3 frases: ¿qué acción haces tú para cuidar tu ciudad?"}]},
  "p2:Nov:1": {"title": "El Mapa de Mi Comunidad", "steps": [{"type": "hook", "kicker": "Un mapa muy grande", "h": "¿Sabes en qué comunidad vives?", "scenario": "Sofía despliega un mapa enorme sobre la mesa. '¿Todo esto es mi comunidad?', pregunta sorprendida.", "body": "España se divide en comunidades autónomas. Cada una tiene provincias, como piezas de un puzle."}, {"type": "theory", "kicker": "Geografía de España", "h": "¿Qué es una comunidad autónoma?", "body": "Una comunidad autónoma es una gran región de España. Dentro de ella hay varias provincias, como piezas más pequeñas.", "diagram": "<b>Mi comunidad autónoma</b><br>- Tiene un nombre propio<br>- Se divide en provincias<br>- Tiene una capital<br>- Aparece en el mapa de España"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Un pequeño reto", "q": "¿Qué forma una comunidad autónoma?", "opts": [{"t": "Varias provincias juntas", "ok": true}, {"t": "Un solo pueblo pequeño", "ok": false}, {"t": "Un río muy largo", "ok": false}], "okMsg": "¡Correcto! Las provincias juntas forman una comunidad autónoma.", "noMsg": "Casi. Una comunidad autónoma está formada por varias provincias."}, {"type": "reflect", "kicker": "Mi comunidad, mi mapa", "h": "Colorea y descubre", "body": "Colorea el mapa de tu comunidad autónoma.", "prompt": "Escribe el nombre de las provincias que la forman."}]},
  "p2:Nov:2": {"title": "Pueblos de Mi Provincia", "steps": [{"type": "hook", "kicker": "Vecinos de mi provincia", "h": "¿Qué municipios hay cerca del tuyo?", "scenario": "En el coche, camino de la playa, Iván ve carteles con nombres de pueblos que no conoce.", "body": "Tu provincia tiene muchos municipios. Cada uno tiene algo especial que lo hace único."}, {"type": "theory", "kicker": "Municipios de mi provincia", "h": "¿Qué hace especial a un municipio?", "body": "Cada municipio de tu provincia tiene algo característico: un monumento, una fiesta, un producto o un paisaje especial.", "diagram": "<b>Cosas características de un municipio</b><br>- Un monumento famoso<br>- Una fiesta popular<br>- Un producto típico<br>- Un paisaje especial"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Piensa un momento", "q": "¿Qué puede hacer especial a un municipio?", "opts": [{"t": "Un monumento, una fiesta o un producto típico", "ok": true}, {"t": "Que tenga muchas farolas", "ok": false}, {"t": "Que tenga un color de casas concreto", "ok": false}], "okMsg": "¡Muy bien! Cada municipio tiene algo propio que lo distingue.", "noMsg": "Piensa de nuevo: un monumento, una fiesta o un producto típico lo hacen especial."}, {"type": "reflect", "kicker": "Mi comunidad, mi mapa", "h": "Investiga en casa", "body": "Busca con un adulto 3 municipios importantes de tu provincia.", "prompt": "Escribe algo característico de cada uno de los 3 municipios."}]},
  "p2:Nov:3": {"title": "El Himno de Mi Tierra", "steps": [{"type": "hook", "kicker": "Una canción especial", "h": "¿Conoces el himno de tu comunidad?", "scenario": "En la fiesta del colegio, todos cantan una canción que Marcos no conocía. '¡Es el himno de nuestra tierra!', dice la maestra.", "body": "Cada comunidad autónoma tiene una canción propia. Se llama himno y habla de su historia y su gente."}, {"type": "theory", "kicker": "El himno autonómico", "h": "¿Qué es un himno?", "body": "Un himno es una canción que representa a un lugar. Sus palabras hablan de su tierra, su gente o su historia.", "diagram": "<b>El himno de mi comunidad</b><br>- Tiene una letra propia<br>- Se canta en fiestas importantes<br>- Habla de la tierra y su gente<br>- Se aprende de memoria poco a poco"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Un pequeño reto", "q": "¿Qué es el himno de una comunidad autónoma?", "opts": [{"t": "Una canción que representa a esa tierra", "ok": true}, {"t": "Un tipo de bandera", "ok": false}, {"t": "Un baile tradicional", "ok": false}], "okMsg": "¡Exacto! El himno es una canción que representa a la comunidad.", "noMsg": "No exactamente. El himno es una canción que representa a la comunidad."}, {"type": "reflect", "kicker": "Mi comunidad, mi mapa", "h": "Aprende y practica", "body": "Escucha con un adulto el himno de tu comunidad autónoma.", "prompt": "Escribe 2-3 frases del himno que más te gusten."}]},
  "p2:Nov:4": {"title": "La Tierra Es del Señor", "steps": [{"type": "hook", "kicker": "Un regalo muy grande", "h": "¿De quién es toda la tierra?", "scenario": "Desde la montaña, Elena mira los campos, los pueblos y el mar a lo lejos. 'Qué tierra tan bonita', piensa.", "body": "La Biblia dice que toda la tierra, con sus montañas, ríos y pueblos, pertenece a Dios."}, {"type": "theory", "kicker": "La Biblia y la tierra", "h": "Del Señor es la tierra", "body": "El Salmo 24 dice que la tierra y todo lo que hay en ella son de Dios. Nuestra comunidad también es parte de su creación.", "diagram": "<b>Salmo 24:1</b><br>'Del Señor es la tierra y su plenitud; el mundo y los que en él habitan.'<br>- Dios creó cada región<br>- Cada persona es importante para Él"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Piensa un momento", "q": "Según el Salmo 24:1, ¿de quién es la tierra?", "opts": [{"t": "Del Señor", "ok": true}, {"t": "De los reyes antiguos", "ok": false}, {"t": "De nadie en especial", "ok": false}], "okMsg": "¡Muy bien! El Salmo dice que la tierra y todo lo que hay en ella son del Señor.", "noMsg": "Recuerda: el Salmo 24:1 dice que la tierra es del Señor."}, {"type": "reflect", "kicker": "Mi comunidad, mi mapa", "h": "Mi mapa terminado", "body": "Ya conoces las provincias, algunos municipios y el himno de tu comunidad.", "prompt": "En tu mapa, escribe una frase: ¿qué te gusta de la variedad de tu comunidad?"}]},
  "p2:Dic:1": {"title": "Las tradiciones navideñas de mi tierra", "steps": [{"type": "hook", "kicker": "Diciembre · Semana 1", "h": "¡Descubre la Navidad de tu tierra!", "scenario": "Imagina que un amigo de otro país viene a pasar la Navidad contigo este año.", "body": "Quiere saber cómo celebra la Navidad tu comunidad autónoma. ¿Qué le contarías primero?"}, {"type": "theory", "kicker": "Aprende", "h": "Cada tierra celebra a su manera", "body": "En España, cada comunidad autónoma tiene tradiciones navideñas propias. Unas cantan villancicos distintos, otras tienen figuras especiales. Todas recuerdan el mismo mensaje: el nacimiento de Jesús.", "diagram": "<b>Tradiciones de España</b><br>• Cataluña: el Tió de Nadal<br>• País Vasco: el Olentzero<br>• Andalucía: las zambombas<br>• Galicia: el apalpador"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué recuerdan todas las tradiciones?", "q": "¿Cuál es el mensaje que comparten todas las tradiciones navideñas de España?", "opts": [{"t": "El nacimiento de Jesús", "ok": true}, {"t": "El fin de las clases", "ok": false}, {"t": "El inicio del verano", "ok": false}], "okMsg": "¡Exacto! Cada región lo celebra a su manera, pero el motivo es el mismo.", "noMsg": "Casi. Todas las tradiciones navideñas recuerdan el nacimiento de Jesús."}, {"type": "reflect", "kicker": "Tu turno", "h": "Investiga tu tradición", "body": "Esta semana vas a investigar la tradición navideña propia de tu comunidad autónoma.", "prompt": "Pregunta a un adulto de tu familia qué tradición navideña es típica de vuestra tierra. Escribe 2 o 3 frases contándola."}]},
  "p2:Dic:2": {"title": "Comparo tradiciones de dos tierras", "steps": [{"type": "hook", "kicker": "Diciembre · Semana 2", "h": "Dos tierras, dos Navidades", "scenario": "Tu amigo ya conoce tu tradición. Ahora quiere conocer la de otra comunidad autónoma.", "body": "Vamos a comparar tu tradición con la de otra parte de España."}, {"type": "theory", "kicker": "Aprende", "h": "Comparar es buscar parecidos y diferencias", "body": "Comparar dos tradiciones significa fijarse en qué es distinto y qué es igual. Así entendemos mejor nuestra propia cultura y respetamos la de los demás.", "diagram": "<b>Cómo comparar</b><br>• Busca 2 diferencias<br>• Busca 1 semejanza<br>• Piensa por qué existe cada tradición"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué es una semejanza?", "q": "Cuando dos tradiciones navideñas se parecen en algo, decimos que tienen una...", "opts": [{"t": "Semejanza", "ok": true}, {"t": "Multiplicación", "ok": false}, {"t": "Frontera", "ok": false}], "okMsg": "¡Correcto! Una semejanza es algo que dos cosas tienen en común.", "noMsg": "No es eso. Semejanza es cuando dos tradiciones se parecen en algo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Compara dos tradiciones", "body": "Elige otra comunidad autónoma distinta a la tuya y compárala con la tuya.", "prompt": "Escribe 2 diferencias y 1 semejanza entre tu tradición y la de esa otra comunidad. Pide ayuda a un adulto si la necesitas."}]},
  "p2:Dic:3": {"title": "Cuento el nacimiento con mis palabras", "steps": [{"type": "hook", "kicker": "Diciembre · Semana 3", "h": "La historia más bonita de la Navidad", "scenario": "Tu amigo quiere escuchar la historia real de la primera Navidad.", "body": "Es hora de contar el nacimiento de Jesús con tus propias palabras."}, {"type": "theory", "kicker": "Aprende", "h": "El relato del nacimiento de Jesús", "body": "María y José viajaron a Belén. No había sitio en la posada, así que Jesús nació en un pesebre. Unos pastores y unos ángeles anunciaron la buena noticia.", "diagram": "<b>El relato bíblico</b><br>• María y José viajan a Belén<br>• Jesús nace en un pesebre<br>• Los ángeles avisan a los pastores<br>• Todos van a adorar al niño"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Dónde nació Jesús?", "q": "Según el relato bíblico, ¿dónde nació Jesús?", "opts": [{"t": "En un pesebre en Belén", "ok": true}, {"t": "En un palacio en Roma", "ok": false}, {"t": "En una cueva en Egipto", "ok": false}, {"t": "En un barco", "ok": false}], "okMsg": "¡Muy bien! Jesús nació en un pesebre, en el pueblo de Belén.", "noMsg": "Recuerda: Jesús nació en un pesebre, en el pueblo de Belén."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe el relato con tus palabras", "body": "Ahora te toca a ti contar esta historia como si se la explicaras a un amigo.", "prompt": "Escribe el relato del nacimiento de Jesús en 6 a 8 oraciones, con tus propias palabras."}]},
  "p2:Dic:4": {"title": "Dibujo la Navidad de mi tierra", "steps": [{"type": "hook", "kicker": "Diciembre · Semana 4", "h": "Un dibujo para tu amigo", "scenario": "Tu amigo se va a su país y quiere llevarse un recuerdo especial.", "body": "Vas a regalarle un dibujo de la Navidad tal y como se vive en tu región."}, {"type": "theory", "kicker": "Aprende", "h": "El versículo de esta semana", "body": "Los ángeles anunciaron a los pastores una gran noticia. Nos recuerda por qué celebramos la Navidad de verdad.", "diagram": "<b>Lucas 2:11</b><br>«Os ha nacido hoy un Salvador,<br>que es Cristo el Señor.»"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué anunciaron los ángeles?", "q": "Según Lucas 2:11, ¿qué gran noticia anunciaron los ángeles a los pastores?", "opts": [{"t": "Que había nacido el Salvador", "ok": true}, {"t": "Que empezaban las vacaciones", "ok": false}, {"t": "Que iba a nevar mucho", "ok": false}], "okMsg": "¡Así es! Anunciaron que había nacido el Salvador, Cristo el Señor.", "noMsg": "Recuerda: anunciaron que había nacido el Salvador, Cristo el Señor."}, {"type": "reflect", "kicker": "Tu turno", "h": "Dibuja tu Navidad", "body": "Este mes tu proyecto es comparar tradiciones de dos comunidades autónomas: la tuya y otra.", "prompt": "Dibuja la escena navideña típica de tu región y ponle una etiqueta con su nombre. Guárdalo para tu proyecto 'Navidad en mi comunidad'."}]},
  "p2:Feb:1": {"title": "Describo el lugar donde vivo", "steps": [{"type": "hook", "kicker": "Febrero · Semana 1", "h": "Un retrato con palabras", "scenario": "Un niño de otro país te escribe una carta preguntando cómo es tu municipio.", "body": "Vas a describirle tu pueblo o ciudad como si fuera un retrato con palabras."}, {"type": "theory", "kicker": "Aprende", "h": "Qué es un texto descriptivo", "body": "Un texto descriptivo cuenta cómo son las personas o los lugares. Habla de sus calles, su paisaje y su gente, con palabras que ayudan a imaginarlo.", "diagram": "<b>Describir un lugar</b><br>• Cómo son las calles<br>• Cómo es el paisaje<br>• Cómo es la gente<br>• Qué se siente al estar allí"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué hace un texto descriptivo?", "q": "¿Qué hace un texto descriptivo sobre un lugar?", "opts": [{"t": "Cuenta cómo es ese lugar", "ok": true}, {"t": "Cuenta lo que pasó ayer", "ok": false}, {"t": "Da instrucciones para cocinar", "ok": false}], "okMsg": "¡Perfecto! Un texto descriptivo cuenta cómo es un lugar o una persona.", "noMsg": "No es eso. Un texto descriptivo cuenta cómo es un lugar o una persona."}, {"type": "reflect", "kicker": "Tu turno", "h": "Describe tu municipio", "body": "Ahora escribe tú una descripción de tu municipio, como si se la enviaras a un amigo lejano.", "prompt": "Escribe 5 a 7 oraciones sobre las calles, el paisaje y la gente de tu municipio."}]},
  "p2:Feb:2": {"title": "Narro un día de mi familia", "steps": [{"type": "hook", "kicker": "Febrero · Semana 2", "h": "Cuéntame qué pasó", "scenario": "Tu abuela vive lejos y quiere saber cómo es un día normal en tu casa.", "body": "Vas a contarle un día de tu familia como si fuera un cuento."}, {"type": "theory", "kicker": "Aprende", "h": "Inicio, nudo y desenlace", "body": "Un texto narrativo cuenta hechos en orden. Empieza con el inicio, sigue con el nudo, donde pasa algo importante, y termina con el desenlace.", "diagram": "<b>Partes de una narración</b><br>• Inicio: cómo empieza el día<br>• Nudo: qué pasa de especial<br>• Desenlace: cómo termina todo"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué es el nudo?", "q": "En una narración, ¿qué es el nudo?", "opts": [{"t": "Donde pasa algo importante", "ok": true}, {"t": "El título del cuento", "ok": false}, {"t": "El dibujo de la portada", "ok": false}], "okMsg": "¡Correcto! El nudo es la parte donde ocurre lo más importante.", "noMsg": "No exactamente. El nudo es la parte donde ocurre lo más importante."}, {"type": "reflect", "kicker": "Tu turno", "h": "Narra tu día", "body": "Ahora te toca narrar un día normal de tu familia con inicio, nudo y desenlace.", "prompt": "Escribe 8 oraciones contando un día normal de tu familia, con inicio, nudo y desenlace."}]},
  "p2:Feb:3": {"title": "Corrijo un texto con errores", "steps": [{"type": "hook", "kicker": "Febrero · Semana 3", "h": "¡Cazadores de errores!", "scenario": "Tu padre ha escrito un texto muy rápido y se le han colado algunos errores.", "body": "Hoy eres un detective de ortografía: tienes que encontrarlos todos."}, {"type": "theory", "kicker": "Aprende", "h": "Ortografía: escribir con cuidado", "body": "La ortografía nos ayuda a escribir las palabras correctamente. Fijarse bien en cada palabra evita errores y hace que todos nos entiendan mejor.", "diagram": "<b>Trucos para corregir</b><br>• Lee despacio, palabra a palabra<br>• Fíjate en las mayúsculas<br>• Revisa los signos de puntuación<br>• Vuelve a leer al final"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Para qué sirve la ortografía?", "q": "¿Para qué sirve escribir con buena ortografía?", "opts": [{"t": "Para que todos nos entiendan mejor", "ok": true}, {"t": "Para escribir más rápido siempre", "ok": false}, {"t": "Para usar más colores", "ok": false}], "okMsg": "¡Muy bien! La buena ortografía ayuda a que nos entiendan mejor.", "noMsg": "No es eso. La buena ortografía ayuda a que nos entiendan mejor."}, {"type": "reflect", "kicker": "Tu turno", "h": "Corrige el texto de papá", "body": "Tu padre ha preparado un texto con 5 errores de ortografía escondidos.", "prompt": "Busca los 5 errores en el texto que preparó tu padre y escríbelos correctamente."}]},
  "p2:Feb:4": {"title": "Hablo con cuidado y pocas palabras", "steps": [{"type": "hook", "kicker": "Febrero · Semana 4", "h": "Menos palabras, más sentido", "scenario": "A veces hablamos muy rápido y decimos cosas sin pensar bien antes.", "body": "Esta semana aprendemos a pensar antes de hablar, con menos palabras."}, {"type": "theory", "kicker": "Aprende", "h": "El versículo de esta semana", "body": "La Biblia nos enseña que es mejor pensar antes de hablar. Usar pocas palabras, bien pensadas, es más sabio que hablar deprisa.", "diagram": "<b>Eclesiastés 5:2</b><br>«No te apresures con tu boca,<br>ni tu corazón se apresure a hablar.»"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué enseña Eclesiastés 5:2?", "q": "Según Eclesiastés 5:2, ¿qué es mejor hacer antes de hablar?", "opts": [{"t": "Pensar bien y no apresurarse", "ok": true}, {"t": "Hablar lo más rápido posible", "ok": false}, {"t": "Hablar sin parar", "ok": false}], "okMsg": "¡Así es! Es mejor pensar bien antes de hablar, sin apresurarse.", "noMsg": "Recuerda: es mejor pensar bien antes de hablar, sin apresurarse."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe con claridad", "body": "Este mes tu cuaderno se llama 'Descripciones de mi mundo', escribiendo con claridad.", "prompt": "Escribe 2 o 3 frases explicando por qué es importante escribir con claridad y pensar antes de hablar."}]},
  "p2:Mar:1": {"title": "Un gigante de piedra romano", "steps": [{"type": "hook", "kicker": "Historia viva", "h": "¿Un puente sin agua?", "scenario": "Imagina caminar por Segovia y ver un puente altísimo hecho solo de piedras, sin pegamento.", "body": "Ese puente se llama acueducto. Los romanos lo construyeron hace casi 2000 años para traer agua a la ciudad. ¡Y todavía sigue en pie!"}, {"type": "theory", "kicker": "Datos romanos", "h": "5 datos para investigar", "body": "Los romanos eran grandes constructores. Busca información sobre el Acueducto de Segovia o el Teatro Romano de Mérida. Necesitas encontrar 5 datos: cuándo se construyó, quién lo mandó hacer, para qué servía, de qué material es y cuántos metros mide.", "diagram": "<b>Mi lista de datos</b><br>1. Fecha de construcción<br>2. Quién lo ordenó<br>3. Para qué servía<br>4. Material usado<br>5. Tamaño en metros"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué monumento es romano?", "q": "¿Cuál de estos lugares construyeron los romanos en España?", "opts": [{"t": "El Acueducto de Segovia", "ok": true}, {"t": "La Torre Eiffel", "ok": false}, {"t": "Las pirámides de Egipto", "ok": false}, {"t": "La Gran Muralla China", "ok": false}], "okMsg": "¡Correcto! El Acueducto de Segovia es una obra romana en España.", "noMsg": "Casi. El Acueducto de Segovia está en España y lo hicieron los romanos."}, {"type": "reflect", "kicker": "Mi investigación", "h": "Anota tus 5 datos", "body": "Ya sabes qué buscar. Ahora es tu turno de investigar con ayuda de un adulto.", "prompt": "Escribe los 5 datos que encontraste sobre tu monumento romano."}]},
  "p2:Mar:2": {"title": "Palabras que vienen del latín", "steps": [{"type": "hook", "kicker": "Un idioma con historia", "h": "¿Hablas latín sin saberlo?", "scenario": "Cuando dices 'agua' o 'familia', estás usando palabras que vienen de un idioma muy antiguo: el latín.", "body": "Los romanos hablaban latín. Con el tiempo, ese idioma se transformó en el castellano que hablamos hoy."}, {"type": "theory", "kicker": "De Roma a España", "h": "Palabras con raíz latina", "body": "Muchas palabras españolas vienen directamente del latín. Por ejemplo, 'aqua' se convirtió en 'agua', y 'familia' se quedó casi igual. Hoy vas a buscar 5 palabras castellanas y descubrir su origen latino.", "diagram": "<b>Ejemplos</b><br>aqua -> agua<br>terra -> tierra<br>schola -> escuela<br>liber -> libro<br>pater -> padre"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿De dónde viene 'escuela'?", "q": "La palabra 'escuela' viene de la palabra latina...", "opts": [{"t": "schola", "ok": true}, {"t": "schoolus", "ok": false}, {"t": "escolarum", "ok": false}, {"t": "skoolia", "ok": false}], "okMsg": "¡Exacto! 'Schola' en latín se convirtió en 'escuela' en castellano.", "noMsg": "No exactamente. La palabra latina es 'schola', muy parecida a 'escuela'."}, {"type": "reflect", "kicker": "Mi lista de palabras", "h": "Busca 5 palabras con raíz latina", "body": "Con ayuda de un diccionario o un adulto, busca palabras en español que vengan del latín.", "prompt": "Escribe las 5 palabras castellanas y la palabra latina de la que vienen."}]},
  "p2:Mar:3": {"title": "Dibuja y localiza el monumento", "steps": [{"type": "hook", "kicker": "Manos a la obra", "h": "¡Convierte tu investigación en arte!", "scenario": "Ya tienes los datos de tu monumento romano. Ahora vas a dibujarlo tal y como lo imaginas.", "body": "Un buen dibujo también cuenta una historia. Vamos a dibujar el monumento y a marcar en el mapa dónde está."}, {"type": "theory", "kicker": "Pasos para dibujar", "h": "Tu dibujo necesita 3 partes", "body": "Primero, dibuja el monumento con sus formas principales, como los arcos del acueducto. Después, escribe su nombre debajo. Por último, dibuja un mapa pequeño de España y marca con una cruz la ciudad donde está.", "diagram": "<b>Mi dibujo debe tener</b><br>1. El monumento dibujado<br>2. Su nombre escrito<br>3. Un mapa de España con la ciudad marcada"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Dónde está el Acueducto?", "q": "¿En qué ciudad de España está el famoso Acueducto romano?", "opts": [{"t": "Segovia", "ok": true}, {"t": "Barcelona", "ok": false}, {"t": "Bilbao", "ok": false}, {"t": "Sevilla", "ok": false}], "okMsg": "¡Correcto! El Acueducto está en Segovia, en el centro de España.", "noMsg": "No es así. El Acueducto romano más famoso está en Segovia."}, {"type": "reflect", "kicker": "Mi obra de arte", "h": "Enseña tu dibujo", "body": "Dibujar ayuda a recordar mejor lo que aprendemos.", "prompt": "Cuenta con tus palabras qué dibujaste y dónde marcaste el monumento en el mapa."}]},
  "p2:Mar:4": {"title": "Dios preparó el momento perfecto", "steps": [{"type": "hook", "kicker": "Un plan perfecto", "h": "¿Por qué construyeron tantos caminos?", "scenario": "Los romanos hicieron calzadas para unir todo su imperio, desde España hasta lejanas tierras.", "body": "Sin saberlo, esos caminos y ese idioma común ayudarían más tarde a que un mensaje muy importante viajara rápido por el mundo."}, {"type": "theory", "kicker": "La Palabra de Dios", "h": "El tiempo perfecto de Dios", "body": "La Biblia dice que Dios preparó el momento exacto para enviar a Jesús. Los caminos romanos y el idioma latín ayudaron a que las buenas noticias de Jesús llegaran a muchos lugares.", "diagram": "<b>Gálatas 4:4</b><br>'Cuando vino el cumplimiento del tiempo, Dios envió a su Hijo.'<br>Roma preparó caminos.<br>Dios preparó el momento."}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué preparó Roma sin saberlo?", "q": "Según lo que aprendimos, ¿para qué sirvieron los caminos y el idioma romano?", "opts": [{"t": "Para que el mensaje de Jesús viajara más rápido", "ok": true}, {"t": "Para jugar partidos de fútbol", "ok": false}, {"t": "Para enviar cartas electrónicas", "ok": false}, {"t": "Para viajar a la Luna", "ok": false}], "okMsg": "¡Muy bien! Dios usó los caminos y el idioma de Roma para su plan.", "noMsg": "Piensa de nuevo: los caminos y el idioma ayudaron a llevar el mensaje de Jesús."}, {"type": "reflect", "kicker": "Mi reflexión", "h": "Roma preparó el camino", "body": "Este mes investigaste el Acueducto o el Teatro romano, palabras latinas y dibujaste un monumento.", "prompt": "Reúne tus 5 datos, tus 5 palabras latinas y tu mapa: así completas 'La herencia de Roma en España'."}]},
  "p2:Abr:1": {"title": "Descubre una cofradía de tu ciudad", "steps": [{"type": "hook", "kicker": "Tradiciones que caminan", "h": "¿Has visto pasar una procesión?", "scenario": "En Semana Santa, grupos de personas llamados cofradías salen a la calle con imágenes y música.", "body": "Cada cofradía tiene una historia propia, un santo patrón y muchos años de tradición."}, {"type": "theory", "kicker": "¿Qué es una cofradía?", "h": "Investiga 3 datos", "body": "Una cofradía es un grupo de personas que se organiza para preparar la Semana Santa. Busca con tu familia una cofradía de tu ciudad y averigua su nombre, su patrón y el año en que se fundó.", "diagram": "<b>Mi investigación</b><br>1. Nombre de la cofradía<br>2. Su patrón<br>3. Año de fundación"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué es una cofradía?", "q": "Una cofradía es...", "opts": [{"t": "Un grupo que organiza la Semana Santa", "ok": true}, {"t": "Un equipo de fútbol", "ok": false}, {"t": "Una tienda de dulces", "ok": false}, {"t": "Un tipo de coche antiguo", "ok": false}], "okMsg": "¡Correcto! Las cofradías organizan las procesiones de Semana Santa.", "noMsg": "No es así. Una cofradía organiza las procesiones de Semana Santa."}, {"type": "reflect", "kicker": "Mi cofradía", "h": "Comparte lo que descubriste", "body": "Pregunta a tu familia o busca en internet con ayuda de un adulto.", "prompt": "Escribe el nombre, el patrón y la fecha de fundación de la cofradía que investigaste."}]},
  "p2:Abr:2": {"title": "Palabras y símbolos de Semana Santa", "steps": [{"type": "hook", "kicker": "Un vocabulario especial", "h": "¿Qué significa 'nazareno'?", "scenario": "En Semana Santa se usan palabras especiales que no escuchamos el resto del año.", "body": "Aprender su significado nos ayuda a entender mejor esta tradición tan importante."}, {"type": "theory", "kicker": "8 palabras para aprender", "h": "Vocabulario de Semana Santa", "body": "Aquí tienes 8 palabras importantes. Búscalas y aprende qué significan. Después, elige 3 y dibújalas.", "diagram": "<b>Vocabulario</b><br>1. Cofradía<br>2. Nazareno<br>3. Paso<br>4. Procesión<br>5. Costalero<br>6. Palio<br>7. Saeta<br>8. Vía Crucis"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué es un 'paso'?", "q": "En Semana Santa, un 'paso' es...", "opts": [{"t": "La imagen que se lleva en procesión", "ok": true}, {"t": "Un paso de baile", "ok": false}, {"t": "Un tipo de pan", "ok": false}, {"t": "Una calle estrecha", "ok": false}], "okMsg": "¡Bien hecho! El 'paso' es la imagen o escena que se lleva por las calles.", "noMsg": "No exactamente. El 'paso' es la imagen que se lleva en la procesión."}, {"type": "reflect", "kicker": "Mis dibujos", "h": "Ilustra 3 palabras", "body": "Elegir y dibujar palabras nos ayuda a recordarlas mejor.", "prompt": "Escribe qué 3 palabras elegiste y describe brevemente tus dibujos."}]},
  "p2:Abr:3": {"title": "Lo que pasó ese fin de semana", "steps": [{"type": "hook", "kicker": "Una historia real", "h": "¿Qué pasó hace tanto tiempo?", "scenario": "Hace más de 2000 años, ocurrieron unos hechos que cambiaron la historia para siempre.", "body": "Hoy vamos a leer en familia lo que pasó ese viernes triste y ese domingo lleno de alegría."}, {"type": "theory", "kicker": "Lectura en familia", "h": "Dos momentos importantes", "body": "Lee con tu familia Marcos 15:33-39, donde Jesús muere en la cruz, y Marcos 16:1-6, donde Jesús resucita. Después, haz un esquema con los hechos en orden.", "diagram": "<b>Mi esquema</b><br>1. Jesús muere en la cruz<br>2. El cielo se oscurece<br>3. Lo ponen en un sepulcro<br>4. Las mujeres van al sepulcro<br>5. ¡El sepulcro está vacío! Jesús resucitó"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué encontraron las mujeres?", "q": "Cuando las mujeres llegaron al sepulcro el domingo, encontraron...", "opts": [{"t": "El sepulcro vacío", "ok": true}, {"t": "A Jesús dormido", "ok": false}, {"t": "Una piedra cerrada para siempre", "ok": false}, {"t": "Nada, no fueron", "ok": false}], "okMsg": "¡Correcto! El sepulcro estaba vacío porque Jesús había resucitado.", "noMsg": "No es así. Las mujeres encontraron el sepulcro vacío: ¡Jesús había resucitado!"}, {"type": "reflect", "kicker": "Mi esquema familiar", "h": "Comparte lo que leísteis", "body": "Leer la Biblia en familia es un momento especial para hablar y preguntar.", "prompt": "Escribe tu esquema con los hechos en orden, desde la cruz hasta el sepulcro vacío."}]},
  "p2:Abr:4": {"title": "Cristo resucitó: primicias de vida", "steps": [{"type": "hook", "kicker": "La gran noticia", "h": "¿Qué significa 'resucitar'?", "scenario": "Después de morir en la cruz, ocurrió algo asombroso: Jesús volvió a estar vivo.", "body": "Esta noticia es el corazón de la Semana Santa y cambia todo para quienes creen en Jesús."}, {"type": "theory", "kicker": "La Palabra de Dios", "h": "Primicias de vida nueva", "body": "La Biblia dice que Jesús resucitó como 'primicias', es decir, el primero de muchos que también resucitarán. Esto nos da esperanza de vida para siempre.", "diagram": "<b>1 Corintios 15:20</b><br>'Cristo resucitó de los muertos; primicias de los que durmieron.'<br>Jesús vive.<br>Hay esperanza para todos."}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué significa que Jesús es 'primicias'?", "q": "Cuando la Biblia dice que Jesús es 'primicias', quiere decir que...", "opts": [{"t": "Es el primero en resucitar, y habrá más", "ok": true}, {"t": "Fue el primer rey de Roma", "ok": false}, {"t": "Fue el primero en nacer", "ok": false}, {"t": "Fue el primero en viajar a España", "ok": false}], "okMsg": "¡Exacto! Jesús resucitó primero, y eso da esperanza a todos los que creen.", "noMsg": "Piensa de nuevo: 'primicias' significa que Jesús fue el primero en resucitar."}, {"type": "reflect", "kicker": "Mi cartel de Semana Santa", "h": "¿Qué cambia esto para mí?", "body": "Este mes investigaste una cofradía, aprendiste palabras y leíste la historia de la cruz y la resurrección.", "prompt": "En tu cartel de Semana Santa, escribe una frase sobre qué significa para ti que Jesús resucitó."}]},
  "p2:May:1": {"title": "Los 5 grandes ríos de España", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "España tiene ríos gigantes", "scenario": "Imagina un río tan largo que tardarías días en caminar junto a él de principio a fin.", "body": "Hoy vas a conocer los <b>5 grandes ríos</b> de España y vas a dibujarlos en un mapa."}, {"type": "theory", "kicker": "La idea", "h": "Cinco ríos, cinco caminos de agua", "body": "Cada río nace en las montañas y viaja por su <b>cuenca</b> hasta llegar al mar.", "diagram": "<b>Los 5 grandes ríos</b><br>Ebro · Tajo · Duero · Guadalquivir · Guadiana"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Cuántos ríos grandes tiene España?", "q": "¿Cuáles son los 5 grandes ríos de España?", "opts": [{"t": "Ebro, Tajo, Duero, Guadalquivir, Guadiana", "ok": true}, {"t": "Nilo, Amazonas, Tajo, Duero, Ebro", "ok": false}, {"t": "Ebro, Sena, Duero, Tíber, Guadiana", "ok": false}, {"t": "Solo el Tajo y el Ebro", "ok": false}], "okMsg": "¡Muy bien! Esos son los 5 grandes ríos de España.", "noMsg": "Casi. Repasa el dibujo: son cinco nombres españoles."}, {"type": "reflect", "kicker": "Tu turno", "h": "Empieza tu mapa", "body": "Dibuja el contorno de España y traza los 5 ríos con su nombre al lado.", "prompt": "Río que más me gustó dibujar: ___\nPor qué: ___"}]},
  "p2:May:2": {"title": "Las montañas que forman España", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "Montañas como murallas naturales", "scenario": "Si viajas de España a Francia, unas montañas enormes te cierran el paso: los Pirineos.", "body": "Hoy descubres las <b>3 cordilleras</b> más importantes de España y las ubicas en el mapa."}, {"type": "theory", "kicker": "La idea", "h": "Tres grandes cordilleras", "body": "Las cordilleras son cadenas de montañas muy largas. España tiene tres muy importantes.", "diagram": "<b>Cordilleras principales</b><br>Pirineos (norte, frontera con Francia)<br>Sistema Central (centro de España)<br>Cordillera Cantábrica (norte, junto al mar)"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Dónde están los Pirineos?", "q": "¿Los Pirineos separan España de qué país?", "opts": [{"t": "Portugal", "ok": false}, {"t": "Francia", "ok": true}, {"t": "Italia", "ok": false}, {"t": "Marruecos", "ok": false}], "okMsg": "¡Exacto! Los Pirineos están en el norte, junto a Francia.", "noMsg": "No es ese país. Los Pirineos están al norte de España."}, {"type": "reflect", "kicker": "Tu turno", "h": "Añade las montañas a tu mapa", "body": "Dibuja las 3 cordilleras en tu mapa de España, cada una en su lugar correcto.", "prompt": "Cordillera más cerca de mi casa: ___"}]},
  "p2:May:3": {"title": "El río de mi ciudad", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "Cada lugar tiene su propio río", "scenario": "Puede que muy cerca de tu casa pase un río, aunque no lo hayas mirado con atención.", "body": "Esta semana investigas el <b>río más cercano</b> a tu ciudad o pueblo."}, {"type": "theory", "kicker": "La idea", "h": "Ser un pequeño investigador", "body": "Para investigar un río necesitas 3 datos: su nombre, su longitud y dónde desemboca.", "diagram": "<b>Mi ficha del río</b><br>Nombre: ___<br>Longitud (km): ___<br>Desemboca en: ___"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué significa \"desembocar\"?", "q": "¿Qué quiere decir que un río \"desemboca\" en el mar?", "opts": [{"t": "Que el río empieza ahí", "ok": false}, {"t": "Que el río termina y entrega su agua al mar", "ok": true}, {"t": "Que el río se seca", "ok": false}, {"t": "Que el río cambia de nombre", "ok": false}], "okMsg": "¡Sí! Desembocar es donde el río termina su viaje.", "noMsg": "Piénsalo de nuevo: desembocar es el final del viaje del río."}, {"type": "reflect", "kicker": "Tu turno", "h": "Completa tu ficha de investigación", "body": "Pregunta a un adulto o busca con ayuda el río más cercano a ti y anota sus datos.", "prompt": "Nombre del río: ___\nLongitud: ___ km\nDesemboca en: ___"}]},
  "p2:May:4": {"title": "Un árbol junto al agua", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "Un árbol que nunca se seca", "scenario": "Hay árboles junto a los ríos que siguen verdes incluso en el verano más caluroso.", "body": "La Biblia usa ese árbol para explicar cómo crece una persona que confía en Dios."}, {"type": "theory", "kicker": "La idea", "h": "El versículo de esta semana", "body": "El Salmo 1:3 compara a la persona buena con un árbol que nunca deja de dar fruto.", "diagram": "<b>Salmo 1:3</b><br>\"Será como árbol plantado junto a corrientes de agua.\"<br>El agua = la Palabra de Dios en tu vida."}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Con qué se compara la persona del Salmo 1?", "q": "Según el Salmo 1:3, ¿con qué se compara a la persona que confía en Dios?", "opts": [{"t": "Con una piedra en el desierto", "ok": false}, {"t": "Con un árbol junto a corrientes de agua", "ok": true}, {"t": "Con una nube que pasa rápido", "ok": false}, {"t": "Con una montaña sin agua", "ok": false}], "okMsg": "¡Correcto! Un árbol junto al agua siempre tiene fuerza para crecer.", "noMsg": "Vuelve a leer el versículo: habla de un árbol junto al agua."}, {"type": "reflect", "kicker": "Tu turno", "h": "Tu mapa terminado", "body": "Termina tu mapa físico de España con los ríos y las montañas, y da gracias por el agua como bendición.", "prompt": "El agua es una bendición porque: ___"}]},
  "p2:Jun:1": {"title": "El español, una lengua de 22 países", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "Tu idioma viaja muy lejos", "scenario": "Si vas a México, Argentina o Guinea Ecuatorial, te entenderán perfectamente al hablar español.", "body": "Hoy descubres que el español es lengua oficial en <b>22 países</b> del mundo."}, {"type": "theory", "kicker": "La idea", "h": "Una lengua, muchos países", "body": "Más de 580 millones de personas hablan español en el mundo, sobre todo en América.", "diagram": "<b>El español en el mundo</b><br>22 países con español oficial<br>+580 millones de hablantes"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Cuántos países hablan español?", "q": "¿En cuántos países el español es lengua oficial?", "opts": [{"t": "En 5 países", "ok": false}, {"t": "En 22 países", "ok": true}, {"t": "Solo en España", "ok": false}, {"t": "En 100 países", "ok": false}], "okMsg": "¡Sí! El español es oficial en 22 países del mundo.", "noMsg": "No es ese número. Repasa el diagrama: son 22 países."}, {"type": "reflect", "kicker": "Tu turno", "h": "Colorea tu mapa mundial", "body": "Colorea en un mapa del mundo los países donde se habla español como lengua oficial.", "prompt": "País hispanohablante que más me gustaría visitar: ___"}]},
  "p2:Jun:2": {"title": "Otras lenguas de España", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "En España se hablan varias lenguas", "scenario": "Un niño en Galicia puede decir \"bo día\" y un niño en el País Vasco puede decir \"egun on\".", "body": "Ambos significan <b>buenos días</b>, pero en lenguas distintas de España."}, {"type": "theory", "kicker": "La idea", "h": "Tres lenguas cooficiales", "body": "Además del castellano, España tiene tres lenguas cooficiales en algunas regiones.", "diagram": "<b>Lenguas cooficiales</b><br>Catalán (Cataluña) — \"Bon dia\"<br>Gallego (Galicia) — \"Bo día\"<br>Euskera (País Vasco) — \"Egun on\""}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué lengua se habla en el País Vasco?", "q": "¿Cuál es la lengua cooficial del País Vasco?", "opts": [{"t": "Catalán", "ok": false}, {"t": "Gallego", "ok": false}, {"t": "Euskera", "ok": true}, {"t": "Portugués", "ok": false}], "okMsg": "¡Correcto! El euskera se habla en el País Vasco.", "noMsg": "No es esa. Mira el diagrama de nuevo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Aprende una frase", "body": "Elige una de las tres lenguas y aprende cómo se dice \"buenos días\".", "prompt": "Lengua elegida: ___\nCómo se dice buenos días: ___"}]},
  "p2:Jun:3": {"title": "Refranes con sabiduría", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "Frases cortas, consejos grandes", "scenario": "Tu abuela te dice \"a quien madruga, Dios le ayuda\" cuando te cuesta levantarte a tiempo.", "body": "Los <b>refranes</b> son frases cortas que guardan un consejo útil para la vida."}, {"type": "theory", "kicker": "La idea", "h": "Cinco refranes españoles", "body": "Cada refrán enseña algo práctico, aunque las palabras parezcan un poco antiguas.", "diagram": "<b>5 refranes</b><br>1. A quien madruga, Dios le ayuda<br>2. No dejes para mañana lo que puedas hacer hoy<br>3. Más vale pájaro en mano que ciento volando<br>4. En boca cerrada no entran moscas<br>5. Quien siembra vientos, recoge tempestades"}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué refrán habla de no procrastinar?", "q": "¿Qué refrán aconseja no dejar las cosas para después?", "opts": [{"t": "En boca cerrada no entran moscas", "ok": false}, {"t": "No dejes para mañana lo que puedas hacer hoy", "ok": true}, {"t": "Más vale pájaro en mano que ciento volando", "ok": false}, {"t": "Quien siembra vientos, recoge tempestades", "ok": false}], "okMsg": "¡Muy bien! Ese refrán habla de hacer las cosas a tiempo.", "noMsg": "Ese no es. Busca el refrán que habla de \"mañana\"."}, {"type": "reflect", "kicker": "Tu turno", "h": "Elige tu refrán favorito", "body": "Escoge uno de los 5 refranes y explica con tus palabras qué consejo da.", "prompt": "Mi refrán favorito: ___\nEl consejo que da es: ___"}]},
  "p2:Jun:4": {"title": "Una lengua pura para Dios", "steps": [{"type": "hook", "kicker": "Para empezar", "h": "Las palabras también se cuidan", "scenario": "Igual que cuidas tus juguetes, puedes cuidar tus palabras para que sean buenas y verdaderas.", "body": "La Biblia habla de una lengua limpia que Dios quiere dar a todos los pueblos."}, {"type": "theory", "kicker": "La idea", "h": "El versículo de esta semana", "body": "Sofonías 3:9 dice que Dios devolverá a los pueblos una lengua pura, para hablar bien de Él.", "diagram": "<b>Sofonías 3:9</b><br>\"Entonces devolveré a los pueblos una lengua pura.\"<br>Nuestra lengua es un regalo de Dios."}, {"type": "quiz", "kicker": "Comprueba", "h": "¿Qué promete Dios en Sofonías 3:9?", "q": "Según Sofonías 3:9, ¿qué promete Dios dar a los pueblos?", "opts": [{"t": "Más ríos y montañas", "ok": false}, {"t": "Una lengua pura", "ok": true}, {"t": "Más países", "ok": false}, {"t": "Nuevos refranes", "ok": false}], "okMsg": "¡Correcto! Dios promete una lengua pura para hablar de Él.", "noMsg": "Repasa el versículo: habla de una \"lengua\"."}, {"type": "reflect", "kicker": "Tu turno", "h": "Termina tu cuaderno", "body": "Cierra tu cuaderno \"La lengua castellana viva\" con una frase sobre la lengua como don de Dios.", "prompt": "Mi lengua es un don de Dios porque: ___"}]},
  "p2:Jul:1": {"title": "Mi Libro de España toma forma", "steps": [{"type": "hook", "kicker": "El gran cierre", "h": "¡Ha llegado el momento!", "scenario": "Sofía saca una carpeta llena de mapas, dibujos y fichas de todo el curso. Está a punto de crear algo especial.", "body": "Este año has aprendido sobre ciudades, montañas, ríos, Roma y fiestas de tu tierra. Ahora vas a reunirlo todo en un <b>Libro de España</b> hecho por ti."}, {"type": "theory", "kicker": "Cómo se hace un buen libro", "h": "Portada e índice: la puerta de tu libro", "body": "Todo libro empieza por una portada bonita y un índice que dice qué hay dentro. Tú eres el autor de este libro sobre España.", "diagram": "<b>Mi Libro de España</b><br>1. Portada: tu nombre y un dibujo<br>2. Índice: lista de temas del año<br>3. Páginas: tus mejores trabajos<br>4. Final: tu reflexión"}, {"type": "quiz", "kicker": "Repaso rápido", "h": "¿Qué va primero en un libro?", "q": "Cuando abres un libro nuevo, ¿qué encuentras primero?", "opts": [{"t": "La portada", "ok": true}, {"t": "El último capítulo", "ok": false}, {"t": "Las notas del profesor", "ok": false}], "okMsg": "¡Correcto! La portada da la bienvenida a quien lo lea.", "noMsg": "Casi. La portada es la primera página, la que presenta el libro."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Empieza tu portada", "body": "Elige un título para tu libro, como \"España, mi tierra\" o \"Un año descubriendo España\".", "prompt": "Dibuja hoy la portada de tu Libro de España y escribe el índice con 4 o 5 temas que aprendiste este año."}]},
  "p2:Jul:2": {"title": "Lo que aprendí y lo que quiero saber", "steps": [{"type": "hook", "kicker": "Un año de descubrimientos", "h": "¡Cuántas cosas nuevas!", "scenario": "Sofía recuerda el día que aprendió sobre los romanos, y también el día que dibujó el mapa de su comunidad autónoma.", "body": "A veces aprendemos algo y nos encanta. Otras veces nos quedamos con ganas de saber más. ¡Las dos cosas son geniales!"}, {"type": "theory", "kicker": "Repasando el curso", "h": "Un viaje por España entera", "body": "Este año viajaste sin moverte de casa: por tu ciudad, tu comunidad, la historia de Roma, la Semana Santa, los ríos y montañas, y el español que se habla en tantos países.", "diagram": "<b>Temas del año</b><br>Mi ciudad y mi comunidad<br>Navidad en mi región<br>Los romanos en España<br>Semana Santa<br>Ríos y relieve<br>El español en el mundo"}, {"type": "quiz", "kicker": "Repaso rápido", "h": "¿Por qué contamos lo que aprendimos?", "q": "¿Para qué sirve pensar en lo que aprendiste este año?", "opts": [{"t": "Para recordarlo mejor y valorarlo", "ok": true}, {"t": "Para olvidarlo más rápido", "ok": false}, {"t": "Para no hablar nunca más de ello", "ok": false}, {"t": "Para llenar una hoja sin sentido", "ok": false}], "okMsg": "¡Exacto! Recordar lo aprendido ayuda a guardarlo en tu memoria y agradecerlo.", "noMsg": "Piensa de nuevo: repasar lo aprendido nos ayuda a recordarlo y valorarlo."}, {"type": "reflect", "kicker": "Tu página del corazón", "h": "Cinco tesoros y dos preguntas", "body": "Piensa en los momentos del curso que más te gustaron y en lo que aún te da curiosidad.", "prompt": "Escribe en tu libro 5 cosas que te gustó aprender este año y 2 cosas que te gustaría saber más."}]},
  "p2:Jul:3": {"title": "Preparo mi presentación en familia", "steps": [{"type": "hook", "kicker": "¡Ahora te toca hablar!", "h": "Tu voz, tu momento", "scenario": "Sofía reúne a su familia en el salón. Tiene su Libro de España en las manos y el corazón un poco nervioso.", "body": "Contar lo que aprendiste en voz alta es una forma bonita de compartir tu esfuerzo de todo el año."}, {"type": "theory", "kicker": "Hablar con calma y claridad", "h": "Cómo preparar 4 minutos geniales", "body": "No hace falta memorizar todo. Elige 3 o 4 momentos que te encantaron y cuéntalos con tus propias palabras, mirando a tu familia.", "diagram": "<b>Mi presentación</b><br>1. Saludo: mi nombre y mi tema<br>2. Lo más interesante que aprendí<br>3. Un dibujo o página que enseño<br>4. Gracias por escuchar"}, {"type": "quiz", "kicker": "Repaso rápido", "h": "¿Cómo hablo mejor ante mi familia?", "q": "¿Qué te ayuda a hacer una buena presentación oral?", "opts": [{"t": "Hablar despacio y mirar a quien escucha", "ok": true}, {"t": "Hablar muy rápido y bajito", "ok": false}, {"t": "Esconder el libro y no enseñar nada", "ok": false}], "okMsg": "¡Muy bien! Hablar despacio y mirar a tu familia hace que te entiendan y disfruten.", "noMsg": "Recuerda: hablar despacio y mirar a quien te escucha ayuda mucho."}, {"type": "reflect", "kicker": "Ensayo en casa", "h": "Practica tu momento especial", "body": "Practicar antes te da seguridad y calma los nervios, igual que ensayar un juego nuevo.", "prompt": "Ensaya hoy tu presentación de 4 minutos delante de un familiar y anota qué parte te gustó más contar."}]},
  "p2:Jul:4": {"title": "Gracias por España, mi lengua e historia", "steps": [{"type": "hook", "kicker": "Un cierre con gratitud", "h": "El final de un gran viaje", "scenario": "La familia de Sofía se sienta junta. Ha llegado la última semana del curso, y el corazón de Sofía está lleno de gratitud.", "body": "Después de un año aprendiendo sobre España, su historia y su lengua, es momento de dar gracias en familia."}, {"type": "theory", "kicker": "Guardar en el corazón", "h": "Recordar para no olvidar", "body": "La Biblia nos anima a guardar en el corazón lo que hemos vivido y aprendido, para no olvidarlo nunca.", "diagram": "<b>Deuteronomio 4:9</b><br>\"Guarda tu alma para que no olvides<br>las cosas que tus ojos han visto.\"<br>Guardamos: nuestro país,<br>nuestra lengua y nuestra historia"}, {"type": "quiz", "kicker": "Repaso rápido", "h": "¿Por qué damos gracias?", "q": "Según el versículo de hoy, ¿qué debemos hacer con lo que hemos visto y aprendido?", "opts": [{"t": "Guardarlo en el corazón y no olvidarlo", "ok": true}, {"t": "Olvidarlo lo antes posible", "ok": false}, {"t": "Guardarlo solo un día", "ok": false}, {"t": "No compartirlo nunca en familia", "ok": false}], "okMsg": "¡Así es! Guardamos en el corazón lo aprendido para recordarlo siempre.", "noMsg": "Repasa el versículo: nos pide guardar en el alma lo que hemos visto, para no olvidarlo."}, {"type": "reflect", "kicker": "Oración final del curso", "h": "Damos gracias en familia", "body": "Reúnete con tu familia y da gracias por tu país, por la lengua que hablas y por la historia que habéis aprendido juntos.", "prompt": "Haz hoy una oración en familia agradeciendo por España, el español y la historia de este año. Cierra tu Libro de España con esta página."}]},
});
